/* =============================================================================
   EKSPOR STAGING FASIH — "FASIH Keluarga" K1/K3 — LANGKAH 2: kolom detail
   -----------------------------------------------------------------------------
   Superset SQL Lab · DB "Starrocks SE 2026" (25) · schema tgr_fd68e454.

   BATCH 3/4 dari export/langkah1_id.csv (total 4350 assignment_id,
   dipecah 4 file supaya statement tidak terlalu panjang). Batch ini: 1100 id.
   SIAP DIJALANKAN — simpan hasilnya sebagai fasih_keluarga_b3.csv, semua
   batch di-APPEND ke tab staging "FASIH Keluarga" yang sama (setelah Query A).

   Kolom output SAMA PERSIS dengan query_ekspor_fasih_keluarga.sql (Query A) —
   hasilnya di-APPEND (bukan replace) ke baris berikutnya di tab staging
   "FASIH Keluarga" setelah hasil Query A. ORDER BY sengaja tidak dipakai.

   Kalau daftar id terlalu panjang untuk 1 query (SQL Lab/browser mungkin ada
   batas panjang statement), pisah jadi beberapa batch (mis. 1000 id per
   batch) — jalankan & simpan CSV terpisah per batch, semuanya tetap di-append
   ke tab staging yang sama.
   ============================================================================= */
WITH
kel AS (
  SELECT rt.assignment_id
       , COALESCE(rt.level_6_full_code, rt.level_5_full_code, rt.level_4_full_code) AS kode_wilayah
       , rt.umur_krt
       , rt.status_kepemilikan_value
       , rt.luas_lantai
       , rt.sumber_penerangan_value
       , rt.jml_meteran
       , rt.listrik_sebulan
       , rt.pengeluaran_makanan_mingguan
       , rt.pengeluaran_non_makan_bulanan
       , rt.pengeluaran_non_makan_tahunan
       , COALESCE(rt.jumlah_kulkas,0) + COALESCE(rt.jumlah_kulkas_new,0)     AS jumlah_kulkas
       , COALESCE(rt.jumlah_ac    ,0) + COALESCE(rt.jumlah_ac_new    ,0)     AS jumlah_ac
       , COALESCE(rt.jumlah_laptop,0) + COALESCE(rt.jumlah_laptop_new,0)     AS jumlah_laptop
  FROM tgr_fd68e454.root_table rt
  WHERE rt.ada_keluarga_value IN ('1','2')
    AND rt.assignment_id IN ( '0fa80fa1-6fba-4de5-8420-4c4baa0e258e','39f7d035-d8ab-40c8-9b26-e4920bddc998','f154afe4-951d-495d-beec-5abd41d94009','a721239e-e0ab-43b9-96bd-d4a0dd22f19d','27ddfd9c-2d02-456a-9065-2a1d9ef00975','ab879893-e4cc-4cdd-bae7-52ec266d5dba','ef1b3f25-b572-4712-9ceb-efcbf040758d','ac568032-338b-4568-a030-ecb61bba58c4','0f41f12e-2007-4934-9694-6f28252c5da1','f2de8f8d-041a-4763-89b7-578baf6a9771','fc76d11f-5ea1-4908-8cd3-43502dd3ca8e','93924fe4-3140-4b39-ab7a-3b8081d73451','28b37a8b-6377-4514-8a78-f4eccf41875a','bf09d8ee-47ac-4956-9446-db43f4cd5ab9','ea0b3c77-fba3-4972-b94b-6f682ef3d700','c3c2c593-c8dd-473d-914b-8d8cc00bddc7','90679492-ea5b-43d0-a077-679fdaf8beef','76e891c2-7840-4a33-91dc-f6b9766c630d','2247e619-4c8e-4696-8658-04d58ef8cd12','6f37b5e9-9e64-41c9-b2ae-7f6b5b497fbb','a228353a-bcd9-4ab0-9f29-6c19656409e3','b4d8a046-7341-40d8-9385-e71babdc1e68','dfd7499a-1de4-41bc-9983-b61f0a91a1d0','0de79dff-e98a-480c-bea0-5a40d03cee6a','72cd1b6e-9859-4563-b0ea-9d23fe6bab54','d13504a4-acc6-41b2-a9ff-34e27f4a768f','e722f608-5264-4d73-92fa-09ec744aeacb','7a9eb9a6-ad33-42f8-bb35-c2b5da4d5b6b','1ae68b56-b8ee-43be-8f7e-2b8b843ef6e9','192e339c-6461-45a4-85f2-56983cc12cac','f8661d55-b153-41a5-8c29-640c9229fd21','2e63fdd9-865c-4d2c-a4aa-5a0b2c6a491a','cbb2df97-e1e3-4190-a5b8-0e032ee50344','0db4b0a0-4504-436c-89af-999575d9eb16','85fd5161-5e98-45a9-bda1-4a8d6ac1c7e0','4e566621-93e5-46d0-ad96-0318ea145ae5','2461bfb4-3ba1-4132-a621-5518397c9fcf','acb96984-d9fa-4ae1-83d0-aca996fa6e79','a118ddaa-05f1-4cb1-9dff-1c245ac0d0af','4988b345-1ab7-4b6b-8041-90b0b4cf8aa9','c5e2c0c7-2cc7-4a53-8c60-09a26a117e6a','c78b1d76-6af8-4e31-9caf-b706ef35cfb0','8d8279a6-c743-4986-b293-e47afcc782a9','5063bf32-4e76-4f52-ae28-4dbf2edc4a53','7a87b8f9-31c0-44fb-ad71-f1e798792996','35405f36-d6d5-4c4d-8e4b-736f2be1b70b','1ef0e502-f639-43ab-82bb-36e7a3392544','87a00fca-42df-45e3-9a15-ef0359023eeb','cce8c0e3-3f8e-41d5-8f68-a5891e36d498','46680cfe-615c-43d0-8802-c90ed39c9605','bc1be62a-f010-4522-